static uint16_t decrement16(uint16_t value){return(uint16_t)(value-1u);} static uint16_t abs_delta16(int16_t a,int16_t b){int32_t d=(int32_t)a-(int32_t)b;if(d<0)d=-d;return(uint16_t)d;}
