bool dk1_player_state_step_compact(Dk1PlayerStateFrame*f,Dk1PlayerStateInputs in,Dk1PlayerStateResult*r){int32_t velocity;if(!f||!r||!dk1_player_state_compact_is_translated(f->state))return false;memset(r,0,sizeof(*r));r->translated=true;switch(f->state){case 6u:f->aux_flags_1271|=0x8000u;r->required_calls=DK1_PLAYER_CALL_AA08|DK1_PLAYER_CALL_AFE4|DK1_PLAYER_CALL_B012;if(f->world_x==f->target_x&&f->world_y==f->target_y){f->aux_flags_1699&=0xFFF7u;f->state=2u;r->finished=true;}else r->required_calls|=DK1_PLAYER_CALL_MOVE;break;case 7u:case 8u:r->required_calls=DK1_PLAYER_CALL_GUARD;r->input_mode=(uint16_t)(f->state-5u);if(!in.guard_aborted)r->required_calls|=DK1_PLAYER_CALL_INPUT|DK1_PLAYER_CALL_MOVE;else r->finished=true;break;case 9u:f->flags_0579|=2u;if(in.gate_carry){f->state=0xCu;f->field_0d11=f->field_0ae5=f->field_11a1=0u;r->finished=true;break;}f->field_11a1=0u;if(f->flags_12a5&2u){f->velocity_y=0x0800;f->velocity_x=0x0400;f->subvelocity_x=0x0400;}r->required_calls=DK1_PLAYER_CALL_AF97|DK1_PLAYER_CALL_MOVE;if(abs_delta16(f->world_x,in.post_move_x)>=4u)f->timer_1375=0u;else f->timer_1375=(uint16_t)(f->timer_1375+1u);if(f->timer_1375>=8u){f->velocity_y=f->velocity_x=f->subvelocity_x=0;f->state=0x54u;r->effect_id=0x68u;r->finished=true;}break;case 11u:f->flags_0579|=2u;velocity=(int32_t)f->velocity_y-0x70;if(velocity<-0x600)velocity=-0x600;f->velocity_y=(int16_t)velocity;r->required_calls=DK1_PLAYER_CALL_MOVE;break;case 12u:r->finished=true;break;case 13u:f->flags_0579|=2u;r->required_calls=DK1_PLAYER_CALL_MOVE;break;case 14u:f->timer_1375=decrement16(f->timer_1375);if(f->timer_1375&0x8000u){f->state=0xAu;r->effect_id=f->game_mode==3u?0xFu:0x14u;r->required_calls=DK1_PLAYER_CALL_A4D5;r->finished=true;}break;case 15u:case 16u:r->input_mode=(uint16_t)(f->state-11u);r->required_calls=DK1_PLAYER_CALL_INPUT|DK1_PLAYER_CALL_MOVE;break;case 17u:r->required_calls=DK1_PLAYER_CALL_MOVE;break;case 18u:r->required_calls=DK1_PLAYER_CALL_GUARD;r->input_mode=6u;if(in.guard_aborted){r->finished=true;break;}r->required_calls|=DK1_PLAYER_CALL_INPUT|DK1_PLAYER_CALL_COLLIDE|DK1_PLAYER_CALL_MOVE;f->velocity_y=-1;if(in.collision_carry){f->velocity_x=0;f->subvelocity_x=0;}break;case 19u:r->required_calls=DK1_PLAYER_CALL_GUARD;r->input_mode=6u;if(in.guard_aborted){r->finished=true;break;}r->required_calls|=DK1_PLAYER_CALL_INPUT|DK1_PLAYER_CALL_COLLIDE|DK1_PLAYER_CALL_MOVE|DK1_PLAYER_CALL_EVENTS;if(in.collision_carry){f->velocity_x=0;f->subvelocity_x=0;}break;default:return false;}return true;}
